use crate::wasi::clocks::wall_clock;

struct Node;

/// Converts whole seconds since the Unix epoch into a `YYYY-MM-DD` string.
///
/// Uses the proleptic Gregorian civil-from-days algorithm (Howard Hinnant).
/// The year is clamped so the output is always exactly ten characters.
fn format_date(unix_secs: u64) -> String {
    let days = (unix_secs / 86_400) as i64;

    // Shift epoch from 1970-01-01 to 0000-03-01.
    let z = days + 719_468;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let doe = z - era * 146_097; // [0, 146096]
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365; // [0, 399]
    let mut year = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100); // [0, 365]
    let mp = (5 * doy + 2) / 153; // [0, 11]
    let day = doy - (153 * mp + 2) / 5 + 1; // [1, 31]
    let month = if mp < 10 { mp + 3 } else { mp - 9 }; // [1, 12]
    if month <= 2 {
        year += 1;
    }

    if year > 9999 {
        return String::from("9999-12-31");
    }

    format!("{:04}-{:02}-{:02}", year, month, day)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        // One clock read serves both the date and the start instant,
        // so the two fields always describe the same moment.
        let now = wall_clock::now();
        RunInfo {
            date: format_date(now.seconds),
            started: now.seconds,
        }
    }
}

export!(Node);
